          const fotoPrevia = porAplicar.map(({ el }) => ({ el, prev: String(el.value == null ? "" : el.value) }));
          porAplicar.forEach(({ el, texto }) => setNgValue(el, texto));
          _vglGuardarDeshacer(extractPacienteAbierto(), fotoPrevia, "Normalidad fija");
