      const cruda = filas[h] || [];
      const cab = Array.from({ length: cruda.length }, (_, i) => String(cruda[i] == null ? "" : cruda[i]).trim().toUpperCase());
      if (cab.filter(Boolean).length < 2) continue;
      if (findDocIdx(cab) < 0) continue;
